     <a class="skip-link" href="#main-content">Skip to main content</a>
     <main id="main-content">
       <div id="app"></div>
     </main>

     <script>
       const quizQuestions = [
         {
           id: "q1",
           prompt: "Which of these are commonly used programming languages?",
           help: "Select every answer that is a programming language. More than one answer may be correct.",
           choices: [
             { id: "q1-python", label: "Python", correct: true },
             { id: "q1-html", label: "HTML", correct: false },
             { id: "q1-ruby", label: "Ruby", correct: true },
             { id: "q1-sql", label: "SQL", correct: true }
           ]
         },
         {
           id: "q2",
           prompt: "Which languages are often used for web browser interactivity?",
           choices: [
             { id: "q2-javascript", label: "JavaScript", correct: true },
             { id: "q2-typescript", label: "TypeScript", correct: true },
             { id: "q2-css", label: "CSS", correct: false },
             { id: "q2-bash", label: "Bash", correct: false }
           ]
         },
         {
           id: "q3",
           prompt: "Which languages are typically compiled before they run?",
           choices: [
             { id: "q3-c", label: "C", correct: true },
             { id: "q3-go", label: "Go", correct: true },
             { id: "q3-java", label: "Java", correct: true },
             { id: "q3-markdown", label: "Markdown", correct: false }
           ]
         }
       ];

       function escapeHtml(value) {
         return value.replace(/[&<>"']/g, (character) => {
           const entities = {
             "&": "&amp;",
             "<": "&lt;",
             ">": "&gt;",
             '"': "&quot;",
             "'": "&#39;"
           };
           return entities[character];
         });
       }

       function Choice({ questionId, choice }) {
         return `
           <div class="choice">
             <input id="${choice.id}" name="${questionId}" type="checkbox" value="${escapeHtml(choice.label)}">
             <label for="${choice.id}">${escapeHtml(choice.label)}</label>
           </div>
         `;
       }

       function QuestionField({ question, index }) {
         const helpId = question.help ? `${question.id}-help` : "";
         const describedBy = helpId ? ` aria-describedby="${helpId}"` : "";
         const helpText = question.help
           ? `<p class="help-text" id="${helpId}">${escapeHtml(question.help)}</p>`
           : "";

         return `
           <div class="form-field">
             <fieldset${describedBy}>
               <legend>${index + 1}. ${escapeHtml(question.prompt)}</legend>
               ${helpText}
               <div class="choices">
                 ${question.choices.map((choice) => Choice({ questionId: question.id, choice })).join("")}
               </div>
             </fieldset>
           </div>
         `;
       }

       function QuizApp({ questions }) {
         return `
           <section class="quiz-shell" aria-labelledby="quiz-title">
             <div class="hero">
               <p class="eyebrow">Multi-select quiz</p>
               <h1 id="quiz-title">Computer Languages</h1>
               <p class="intro">Choose all answers that apply for each question, then submit your selections to see your score.</p>
             </div>
             <form id="quiz-form">
               ${questions.map((question, index) => QuestionField({ question, index })).join("")}
               <div class="actions">
                 <button type="submit">Submit answers</button>
                 <div id="quiz-status" role="status"></div>
               </div>
               <div class="results" id="quiz-results" aria-live="polite"></div>
             </form>
           </section>
         `;
       }

       function getSelectedLabels(form, questionId) {
         return Array.from(form.querySelectorAll(`input[name="${questionId}"]:checked`))
           .map((input) => input.value)
           .sort();
       }

       function arraysMatch(first, second) {
         return first.length === second.length && first.every((value, index) => value === second[index]);
       }

       function handleSubmit(event) {
         event.preventDefault();

         const form = event.currentTarget;
         const results = quizQuestions.map((question) => {
           const selected = getSelectedLabels(form, question.id);
           const correct = question.choices
             .filter((choice) => choice.correct)
             .map((choice) => choice.label)
             .sort();

           return {
             prompt: question.prompt,
             selected,
             correct,
             isCorrect: arraysMatch(selected, correct)
           };
         });

         const score = results.filter((result) => result.isCorrect).length;
         const status = document.querySelector("#quiz-status");
         const resultRegion = document.querySelector("#quiz-results");

         status.textContent = `You scored ${score} out of ${quizQuestions.length}.`;
         resultRegion.innerHTML = `
           <h2>Results</h2>
           <ol>
             ${results.map((result) => `
               <li>
                 <strong>${result.isCorrect ? "Correct" : "Review"}:</strong>
                 ${escapeHtml(result.prompt)}
                 Correct answer${result.correct.length === 1 ? "" : "s"}:
                 ${result.correct.map(escapeHtml).join(", ")}.
               </li>
             `).join("")}
           </ol>
         `;
       }

       document.querySelector("#app").innerHTML = QuizApp({ questions: quizQuestions });
       document.querySelector("#quiz-form").addEventListener("submit", handleSubmit);
     </script>
